function kurmanjiValue(value) {
  if (KU_TEXT[value]) return KU_TEXT[value];
  let match = value.match(/^(\d+) products · Shop now →$/);
  if (match) return `${match[1]} berhem · Niha bikire →`;
  match = value.match(/^(\d+) products from verified sellers$/);
  if (match) return `${match[1]} berhem ji firoşkarên bawerbar`;
  match = value.match(/^SAVE (\d+)%$/);
  if (match) return `Xilasîna ${match[1]}%`;
  match = value.match(/^(\d+)% off$/);
  if (match) return `${match[1]}% daxistin`;
  match = value.match(/^([\d,]+) reviews$/);
  if (match) return `${match[1]} nirxandin`;
  match = value.match(/^(\d+) items? from (\d+) seller\(s\)$/);
  if (match) return `${match[1]} berhem ji ${match[2]} firoşkaran`;
  match = value.match(/^✦ ([\d.]+)k\+ sellers$/);
  if (match) return `✦ ${match[1]}k+ firoşkar`;
  match = value.match(/^✦ ([\d.]+)m\+ products$/);
  if (match) return `✦ ${match[1]}m+ berhem`;
  match = value.match(/^✦ ([\d.]+)\/5 trust$/);
  if (match) return `✦ ${match[1]} / 5 bawerî`;
  match = value.match(/^of (\d+) registered$/);
  if (match) return `ji ${match[1]} qeydkirî`;
  match = value.match(/^(\d+) pending$/);
  if (match) return `${match[1]} li bendê`;
  if (value.startsWith("Customer: ")) return value.replace("Customer: ", "Xerîdar: ");
  if (value.startsWith("Admin: ")) return value.replace("Admin: ", "Rêveber: ");
  match = value.match(/^Reviews \((\d+)\)$/);
  if (match) return `Nirxandin (${match[1]})`;
  match = value.match(/^Feature (\d+):/);
  if (match) return value.replace(`Feature ${match[1]}:`, `Taybetmendî ${match[1]}:`);
  match = value.match(/^(\d+) in stock$/);
  if (match) return `${match[1]} di stokê de ye`;
  match = value.match(/^★ (.+) · (\d+)% response$/);
  if (match) return `★ ${match[1]} · ${match[2]}% bersiv`;
  if (value === "30-day returns") return "Vegerrandina 30 rojan";
  match = value.match(/^(\d+) seller\(s\)$/);
  if (match) return `${match[1]} firoşkar`;
  const replaced = value.replaceAll("Free shipping", "Şandina belaş").replaceAll("30-day returns", "Vegerrandina 30 rojan").replaceAll("response", "bersiv").replaceAll("Feature", "Taybetmendî").replaceAll("Applied", "Serlêdan").replaceAll("Jan ", "Rêbendan ").replaceAll("Feb ", "Sibat ").replaceAll("Mar ", "Adar ").replaceAll("Apr ", "Nîsan ").replaceAll("May ", "Gulan ").replaceAll("Jun ", "Hezîran ").replaceAll("Jul ", "Tîrmeh ").replaceAll("Aug ", "Gelawêj ").replaceAll("Sep ", "Îlon ").replaceAll("Oct ", "Cotmeh ").replaceAll("Nov ", "Sermawez ").replaceAll("Dec ", "Berfanbar ");
  if (replaced !== value) return replaced;
  return null;
}

const I18n = {
  lang: "ar",
  init() {
    try { this.lang = localStorage.getItem("nexus_language") || Store.db?.settings?.language || "ar"; } catch (e) { this.lang = Store.db?.settings?.language || "ar"; }
    if (!LANGS[this.lang]) this.lang = "ar";
    this.apply();
  },
  set(lang) {
    if (!LANGS[lang]) return;
    this.lang = lang;
    try { localStorage.setItem("nexus_language", lang); } catch (e) {}
    if (Store.db?.settings) { Store.db.settings.language = lang; Store.save(); }
    this.apply();
    if (typeof App !== "undefined" && App.root) App.render();
  },
  apply() {
    document.documentElement.lang = this.lang;
    document.documentElement.dir = LANGS[this.lang].dir;
    const titles = { ar: "NEXUS — سوق متعدد البائعين", en: "NEXUS — Multi-Vendor Marketplace", ku: "NEXUS — Bazara firoşkarên pirjimar" };
    const descriptions = { ar: "NEXUS — سوق متعدد البائعين للمنتجات والعلامات المستقلة.", en: "NEXUS — production-grade multi-vendor marketplace.", ku: "NEXUS — bazarek pîşesazî ji bo berhem û markayên serbixwe." };
    document.title = titles[this.lang];
    const meta = document.querySelector('meta[name="description"]');
    if (meta) meta.content = descriptions[this.lang];
  },
  translateDom(root) {
    if (!root || this.lang === "en") return;
    const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT);
    const nodes = [];
    while (walker.nextNode()) nodes.push(walker.currentNode);
    nodes.forEach((node) => {
      const value = node.nodeValue.trim();
      const direct = this.lang === "ku" ? kurmanjiValue(value) : null;
      const key = DOM_LABEL_KEYS[value];
      if (direct || key) node.nodeValue = node.nodeValue.replace(value, direct || t(key));
    });
    root.querySelectorAll("input,textarea,select,button,[title],[aria-label]").forEach((el) => {
      ["placeholder", "title", "aria-label"].forEach((attr) => {
        const value = el.getAttribute(attr);
        const translated = this.lang === "ku" && value ? kurmanjiValue(value) : null;
        if (translated) el.setAttribute(attr, translated);
      });
    });
  },
};
function t(key) { return TRANSLATIONS[I18n.lang]?.[key] || TRANSLATIONS.en[key] || key; }
function languageSwitcher(className = "") {
  return h("select", { class: "language-switcher " + className, value: I18n.lang, title: "Language", onchange: (e) => I18n.set(e.target.value) }, Object.entries(LANGS).map(([value, info]) => h("option", { value, selected: value === I18n.lang }, info.label)));
}
function localizedCategory(id) { return t(id === "home" ? "homeLiving" : id); }
function localizedVendor(name) { return I18n.lang === "ku" ? (KU_TEXT[name] || name) : ({ "Solaris Power Ltd": { ar: "سولاريس للطاقة" }, "Voltix Electronics": { ar: "فولتكس للإلكترونيات" }, "IronForge Tools": { ar: "آيرون فورج للأدوات" }, "Casa Verde Home": { ar: "كازا فيردي للمنزل" }, "Atelier Nord": { ar: "أتيليه نورد" } }[name]?.[I18n.lang] || name); }
